package com.nexamart.backend.service;
import com.nexamart.backend.api.ApiModels.*;import com.nexamart.backend.domain.*;import com.nexamart.backend.exception.ApiException;import com.nexamart.backend.repository.*;import com.nexamart.backend.security.CurrentUser;import org.springframework.data.domain.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.*;import java.time.*;import java.util.*;
@Service public class DeliveryService{final OrderRepository orders;final UserAccountRepository users;final DeliveryPartnerProfileRepository profiles;final OrderItemRepository items;final NotificationRepository notes;final EarningRepository earnings;final MappingService map;public DeliveryService(OrderRepository o,UserAccountRepository u,DeliveryPartnerProfileRepository p,OrderItemRepository i,NotificationRepository n,EarningRepository e,MappingService m){orders=o;users=u;profiles=p;items=i;notes=n;earnings=e;map=m;}
 private Long me(){return CurrentUser.id();} private UserAccount partner(){return users.findById(me()).orElseThrow(()->new ApiException(HttpStatus.UNAUTHORIZED,"Session expired."));}
 public DeliveryDashboardResponse dashboard(){
  UserAccount p=partner();
  ZoneId zone=ZoneId.of("Asia/Kolkata");
  LocalDate todayDate=LocalDate.now(zone);
  Instant start=todayDate.atStartOfDay(zone).toInstant();
  Instant end=todayDate.plusDays(1).atStartOfDay(zone).toInstant();
  long active=orders.countByDeliveryPartnerIdAndStatus(p.getId(),OrderStatus.ACCEPTED)+orders.countByDeliveryPartnerIdAndStatus(p.getId(),OrderStatus.PICKED_UP)+orders.countByDeliveryPartnerIdAndStatus(p.getId(),OrderStatus.OUT_FOR_DELIVERY);
  long assigned=orders.countByDeliveryPartnerIdAndStatus(p.getId(),OrderStatus.ASSIGNED)+orders.countByDeliveryPartnerIdAndStatus(p.getId(),OrderStatus.ACCEPTED);
  long picked=orders.countByDeliveryPartnerIdAndStatus(p.getId(),OrderStatus.PICKED_UP);
  long ofd=orders.countByDeliveryPartnerIdAndStatus(p.getId(),OrderStatus.OUT_FOR_DELIVERY);
  long completed=orders.countByDeliveryPartnerIdAndStatusAndDeliveredAtBetween(p.getId(),OrderStatus.DELIVERED,start,end);
  BigDecimal today=earnings.findByPartnerIdAndEarnedAtBetween(p.getId(),start,end).stream().map(Earning::getAmount).filter(Objects::nonNull).reduce(BigDecimal.ZERO,BigDecimal::add);
  List<DeliveryOrderSummary> recent=orders.findByDeliveryPartnerId(p.getId(),PageRequest.of(0,5,Sort.by(Sort.Direction.DESC,"createdAt"))).getContent().stream().map(map::deliverySummary).toList();
  String av=profiles.findById(p.getId()).map(x->x.isAvailable()?"ONLINE":"OFFLINE").orElse("UNKNOWN");
  return new DeliveryDashboardResponse(active,assigned,picked,ofd,completed,today.toString(),"INR",av,recent);
}
 public PageResponse<OrderResponse> orders(int page,int size,String q,OrderStatus status,Instant from,Instant to){UserAccount p=partner();boolean online=profiles.findById(p.getId()).map(DeliveryPartnerProfile::isAvailable).orElse(false); Page<Order> pg=online?orders.partnerSearchIncludingOpen(p.getId(),q,status,from,to,List.of(OrderStatus.PENDING,OrderStatus.READY),PageRequest.of(page,size,Sort.by(Sort.Direction.DESC,"createdAt"))):orders.partnerSearch(p.getId(),q,status,from,to,PageRequest.of(page,size,Sort.by(Sort.Direction.DESC,"createdAt")));return new PageResponse<>(pg.getContent().stream().map(map::order).toList(),pg.getNumber(),pg.getSize(),pg.getTotalPages(),pg.getTotalElements(),pg.hasNext());}
 public OrderResponse detail(Long id){Order o=get(id);if(o.getDeliveryPartner()==null&&!List.of(OrderStatus.PENDING,OrderStatus.READY).contains(o.getStatus()))throw new ApiException(HttpStatus.FORBIDDEN,"Order is not available to this partner.");if(o.getDeliveryPartner()!=null&&!o.getDeliveryPartner().getId().equals(me()))throw new ApiException(HttpStatus.FORBIDDEN,"Order is not assigned to you.");return map.order(o);}
 @Transactional public void action(Long id,ActionRequest r){Order o=get(id);String a=r.action().toUpperCase();if(a.equals("ACCEPT")){if(o.getDeliveryPartner()!=null&&!o.getDeliveryPartner().getId().equals(me()))throw new ApiException(HttpStatus.CONFLICT,"Order is already assigned.");UserAccount p=partner();if(p.getStatus()!=AccountStatus.ACTIVE)throw new ApiException(HttpStatus.FORBIDDEN,"Account is not active.");validateAcceptanceDistance(o, p.getId());o.setDeliveryPartner(p);o.setStatus(OrderStatus.ACCEPTED);o.setAcceptedAt(Instant.now());orders.save(o);notifyUser(o.getCustomer(),"Delivery accepted","Your order #"+o.getId()+" has been accepted.",o);return;}if(o.getDeliveryPartner()==null||!o.getDeliveryPartner().getId().equals(me()))throw new ApiException(HttpStatus.FORBIDDEN,"Order is not assigned to you.");switch(a){case "PICKUP", "PICK_UP"->transition(o,OrderStatus.ACCEPTED,OrderStatus.PICKED_UP);case "OUT_FOR_DELIVERY"->transition(o,OrderStatus.PICKED_UP,OrderStatus.OUT_FOR_DELIVERY);case "COMPLETE"->{transition(o,OrderStatus.OUT_FOR_DELIVERY,OrderStatus.DELIVERED);o.setDeliveredAt(Instant.now());orders.save(o);Earning e=new Earning();e.setPartner(partner());e.setOrder(o);e.setAmount(new BigDecimal("40.00"));e.setDescription("Delivery earning for order #"+o.getId());earnings.save(e);notifyUser(o.getCustomer(),"Order delivered","Your order #"+o.getId()+" was delivered.",o);}default->throw new ApiException(HttpStatus.BAD_REQUEST,"Unsupported delivery action.");}}
 private void transition(Order o,OrderStatus from,OrderStatus to){if(o.getStatus()!=from)throw new ApiException(HttpStatus.CONFLICT,"Order is not in the required status.");o.setStatus(to);if(to==OrderStatus.PICKED_UP)o.setPickedUpAt(Instant.now());if(to==OrderStatus.OUT_FOR_DELIVERY)o.setOutForDeliveryAt(Instant.now());orders.save(o);notifyUser(o.getCustomer(),"Order update","Order #"+o.getId()+" is now "+to.name().replace('_',' ')+".",o);}
 public AvailabilityResponse availability(){DeliveryPartnerProfile p=profiles.findById(me()).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Delivery profile not found."));boolean active=orders.countByDeliveryPartnerIdAndStatus(me(),OrderStatus.ACCEPTED)+orders.countByDeliveryPartnerIdAndStatus(me(),OrderStatus.PICKED_UP)+orders.countByDeliveryPartnerIdAndStatus(me(),OrderStatus.OUT_FOR_DELIVERY)>0;return new AvailabilityResponse(p.isAvailable(),p.isAvailable()?"ONLINE":"OFFLINE",!active,active?"Active delivery in progress.":null,p.getUpdatedAt());}
 @Transactional public AvailabilityResponse updateAvailability(AvailabilityRequest request){DeliveryPartnerProfile p=profiles.findById(me()).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Delivery profile not found."));if(!request.available()&&(!availability().canChange()))throw new ApiException(HttpStatus.CONFLICT,"You cannot go offline during an active delivery.");p.setAvailable(request.available());if(request.latitude()!=null&&request.longitude()!=null){validateCoordinates(request.latitude(),request.longitude());p.setLatitude(request.latitude());p.setLongitude(request.longitude());p.setLocationUpdatedAt(Instant.now());}profiles.save(p);return availability();}
 @Transactional public void updateLocation(Double latitude,Double longitude){validateCoordinates(latitude,longitude);DeliveryPartnerProfile p=profiles.findById(me()).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Delivery profile not found."));if(!p.isAvailable())return;p.setLatitude(latitude);p.setLongitude(longitude);p.setLocationUpdatedAt(Instant.now());profiles.save(p);}
 private void validateCoordinates(Double latitude,Double longitude){if(latitude==null||longitude==null||latitude<-90||latitude>90||longitude<-180||longitude>180)throw new ApiException(HttpStatus.BAD_REQUEST,"Invalid delivery partner location.");}
 private void validateAcceptanceDistance(Order order, Long partnerId){
  DeliveryPartnerProfile profile=profiles.findById(partnerId).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Delivery profile not found."));
  if(!profile.isAvailable())throw new ApiException(HttpStatus.CONFLICT,"You are offline. Please go online before accepting a delivery.");
  Address address=order.getDeliveryAddress();
  if(address==null||address.getLatitude()==null||address.getLongitude()==null)throw new ApiException(HttpStatus.CONFLICT,"Customer delivery location is not available.");
  if(profile.getLatitude()==null||profile.getLongitude()==null||profile.getLocationUpdatedAt()==null||Duration.between(profile.getLocationUpdatedAt(),Instant.now()).toMinutes()>3)throw new ApiException(HttpStatus.CONFLICT,"Your live location is unavailable. Please keep location enabled and try again.");
  long ageSeconds=Math.max(0L,Duration.between(order.getCreatedAt(),Instant.now()).getSeconds());
  double radiusKm=ageSeconds>=120?8.0:5.0;
  double distanceKm=DeliveryDispatchService.distanceKm(address.getLatitude(),address.getLongitude(),profile.getLatitude(),profile.getLongitude());
  if(distanceKm>radiusKm)throw new ApiException(HttpStatus.CONFLICT,String.format("Order is %.1f km away. It is currently available only within %.0f km.",distanceKm,radiusKm));
 }
 public ProfileResponse profile(){UserAccount u=partner();DeliveryPartnerProfile p=profiles.findById(me()).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Delivery profile not found."));return new ProfileResponse(u.getId(),u.getName(),u.getPhone(),u.getEmail(),null,p.getVerificationStatus(),u.getStatus().name(),p.getVehicleType(),p.getVehicleNumber(),p.getLicenseReference(),p.getDateOfBirth(),p.getDrivingLicenseNumber(),p.getAadhaarNumber(),p.getAadhaarPhotoData()==null?null:"/api/v1/delivery/profile/aadhaar-photo",u.getCreatedAt(),u.getLastActiveAt(),List.of("name","email","vehicleType","vehicleNumber","licenseReference","dateOfBirth","drivingLicenseNumber","aadhaarNumber"));}
 public ProfileResponse updateProfile(ProfileUpdate r){UserAccount u=partner();if(r.name()!=null&&!r.name().isBlank())u.setName(r.name());if(r.email()!=null&&!r.email().isBlank())u.setEmail(r.email().toLowerCase());DeliveryPartnerProfile p=profiles.findById(me()).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Delivery profile not found."));if(r.vehicleType()!=null)p.setVehicleType(r.vehicleType());if(r.vehicleNumber()!=null)p.setVehicleNumber(r.vehicleNumber());if(r.licenseReference()!=null)p.setLicenseReference(r.licenseReference());if(r.dateOfBirth()!=null)p.setDateOfBirth(r.dateOfBirth());if(r.drivingLicenseNumber()!=null)p.setDrivingLicenseNumber(r.drivingLicenseNumber());if(r.aadhaarNumber()!=null)p.setAadhaarNumber(r.aadhaarNumber());users.save(u);profiles.save(p);return profile();}
 public PageResponse<NotificationResponse> notifications(int page,int size,boolean unreadOnly){Page<Notification> pg=notes.search(me(),unreadOnly,PageRequest.of(page,size,Sort.by(Sort.Direction.DESC,"createdAt")));List<NotificationResponse> list=pg.getContent().stream().map(n->new NotificationResponse(n.getId().toString(),n.getTitle(),n.getMessage(),n.getCreatedAt(),n.isReadFlag(),n.getType()==null?null:n.getType().name(),n.getOrderId(),n.getActionUrl())).toList();return new PageResponse<>(list,pg.getNumber(),pg.getSize(),pg.getTotalPages(),pg.getTotalElements(),pg.hasNext());}
 public void markRead(Long id){Notification n=notes.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Notification not found."));if(!n.getUser().getId().equals(me()))throw new ApiException(HttpStatus.FORBIDDEN,"Notification is not yours.");n.setReadFlag(true);notes.save(n);}public void markAllRead(){notes.findByUserIdAndReadFlagFalse(me()).forEach(n->{n.setReadFlag(true);notes.save(n);});}
 public EarningsSummary earningsSummary(Instant from,Instant to){Instant now=Instant.now();BigDecimal today=sum(now.minus(1,java.time.temporal.ChronoUnit.DAYS),now),week=sum(now.minus(7,java.time.temporal.ChronoUnit.DAYS),now),month=sum(now.minus(30,java.time.temporal.ChronoUnit.DAYS),now),total=earnings.findByPartnerId(me(),Pageable.unpaged()).getContent().stream().map(Earning::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);long completed=orders.countByDeliveryPartnerIdAndStatus(me(),OrderStatus.DELIVERED);return new EarningsSummary("INR",today,week,month,completed,BigDecimal.ZERO,total);}
 public PageResponse<EarningResponse> earningHistory(int page,int size){Page<Earning> pg=earnings.findByPartnerId(me(),PageRequest.of(page,size,Sort.by(Sort.Direction.DESC,"earnedAt")));return new PageResponse<>(pg.getContent().stream().map(e->new EarningResponse(e.getId().toString(),e.getOrder().getId(),e.getEarnedAt(),e.getAmount(),e.getCurrencyCode(),e.getStatus().name(),e.getDescription())).toList(),pg.getNumber(),pg.getSize(),pg.getTotalPages(),pg.getTotalElements(),pg.hasNext());}
 private BigDecimal sum(Instant a,Instant b){return earnings.findByPartnerIdAndEarnedAtBetween(me(),a,b).stream().map(Earning::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);}private Order get(Long id){return orders.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Order not found."));}private void notifyUser(UserAccount u,String title,String msg,Order o){Notification n=new Notification();n.setUser(u);n.setTitle(title);n.setMessage(msg);n.setType(NotificationType.ORDER_STATUS);n.setOrderId(o.getId());notes.save(n);}}
